import{_ as o,l as i,o as e,c as s,v as r,p as n,x as l,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Earley 解析","description":"","frontmatter":{"title":"Earley 解析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/earley-parser.md","filePath":"cs/earley-parser.md","lastUpdated":1789023840000}'),c={name:"cs/earley-parser.md"};function h(A,a,_,C,y,m){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="earley-解析" tabindex="-1">Earley 解析 <a class="header-anchor" href="#earley-解析" aria-label="Permalink to &quot;Earley 解析&quot;">​</a></h1><div class="epigraph"><p>每一输入位置一张项集：预测、扫描、完成三步推进；任意 CFG 可在立方时间内判定成员，无二义时接近线性。</p><footer>—— 据 Earley, An Efficient Context-Free Parsing Algorithm, 1970；龙书对一般 CFG 分析的对照整理</footer></div><p>上一课<a href="/cs/yacc-bison">yacc / bison</a>要求文法落进 LALR，冲突靠改写或 <code>%left</code>。主干<a href="/cs/cyk-parsing">CYK</a>已证明一般 CFL 可判定，但要 Chomsky 范式。缺口是<strong>不改写文法</strong>的通用分析：Earley 项在原 CFG 上跑，认左递归、认 ε，也认 yacc 拒掉的形状。本课钉项与三步，不把 marpa 实现写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LALR 失败时人改文法，语义动作跟着碎。Earley：项 \\([A\\to\\alpha\\cdot\\beta,\\,j]\\) 挂在位置 \\(i\\)，表示 \\(A\\to\\alpha\\beta\\) 从 \\(j\\) 开始，已吃到 \\(i\\)。预测：点后非终结符则加入其产生式；扫描：点后终结符与当前记号匹配则前进；完成：点到末尾，把等待该非终结符的项推进。缺口是这套动态规划，不是再造 LALR 表。</p><p>复杂度：一般 \\(O(n^3)\\)，无二义 \\(O(n^2)\\)，确定（近似 LR）可近线性。比 CYK 省 CNF 化；比 bison 慢，换的是「任意 CFG」。</p><h3 id="项带起点-不只带点" tabindex="-1">项带起点，不只带点 <a class="header-anchor" href="#项带起点-不只带点" aria-label="Permalink to &quot;项带起点，不只带点&quot;">​</a></h3><p>LR 项活在生成期 DFA 状态里；Earley 项活在输入位置上，起点 \\(j\\) 记录「这段从哪预测」。丢掉 \\(j\\) 就无法完成。这不是 lex 的 DFA 状态。</p><p><span class="marginnote">Earley 1970（CACM）。Leo 的右递归优化改善确定情形。龙书把 Earley 当一般方法，编译器前端仍偏 LR；本进阶课要的是 yacc 覆盖不了时的退路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 \\(i=0\\ldots n\\) 维护项集 \\(S_i\\)。\\(S_0\\) 放入增广产生式的点在左端。循环执行预测/扫描/完成直到闭包。接受：结束位置含 \\([S&#39;\\to S\\cdot,\\,0]\\)。建树：完成步记下前驱指针，事后回溯；二义则森林。</p>',11)),(e(),n(E,null,{default:l(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E4%BB%BB%E6%84%8F%20CFG%22%5D%20--%3E%20S0%5B%22S0%20%E9%A2%84%E6%B5%8B%22%5D%0A%20%20S0%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E8%AE%B0%E5%8F%B7%22%5D%0A%20%20SCAN%20--%3E%20COMP%5B%22%E5%AE%8C%E6%88%90%22%5D%0A%20%20COMP%20--%3E%20PRED%5B%22%E5%86%8D%E9%A2%84%E6%B5%8B%22%5D%0A%20%20PRED%20--%3E%20ACC%5B%22%E6%88%90%E5%91%98%20%2F%20%E6%A3%AE%E6%9E%97%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要把 Earley 当「带回溯的递归下降」：它是按位置的闭包，共享子项，不是指数分叉的朴素搜索。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ε 产生式在预测与完成里要小心重复加入，否则不终止。二义文法给出多棵树，Earley 本身不消二义——消二义是优先级或后课 GLR 的用户规则。</p><p>与 CYK：格子是非终结符×区间；Earley 格子是项×位置。二者都是 CFL 成员的 DP，形状不同。编程语言若已是 LALR，没有理由默认 Earley。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GLR 的分叉栈，不把 PEG 的有序选择当 CFG。不证 Earley 与 CYK 的渐近常数谁优。后课默认：任意 CFG 可 Earley；实用确定文法仍用生成器。下一课 GLR：在 LR 表上对冲突分叉，而不是换一套项。</p><p>工具：部分语言工作台用 Earley/GLL；编辑器增量解析后课再接。此处只要求会画三步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Earley：按位置闭包项集，认任意 CFG。</li><li>三步：预测、扫描、完成；一般立方。</li><li>不替代 bison：LALR 足够时不必通用算法。</li><li>出处：Earley, 1970；对照 Aho et al. 与 Kasami/Younger。</li></ul>',9))])}const L=o(c,[["render",h]]);export{u as __pageData,L as default};
